//! Test-vector loader (also compiled with the `vectors` feature for the phone
//! module's simulator tests, see [`run_json`]): `vectors/codec/*.json` pins the wire for every
//! parser. The vectors are generated by `vectors/codec/gen.py`, an independent
//! Python implementation of the same layouts, so agreement between the two
//! checks both. Each vector round-trips byte-exactly (decode → re-encode →
//! same bytes); error vectors must fail with the named variant. The Go relay
//! (E2a) decodes `header.json` with its own parser against the same file.

use std::path::PathBuf;

use crate::codec::{catalog_blob, header, hs, part, push_plain, record, term};
use crate::ids::Id;

fn dir() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR")).join("vectors/codec")
}

thread_local! {
    /// Vector JSON handed in by [`run_json`] (the phone module's simulator
    /// tests have no source tree to read from).
    static SOURCE: std::cell::RefCell<Option<(String, String)>> = const { std::cell::RefCell::new(None) };
}

fn load(name: &str) -> Vec<serde_json::Value> {
    let injected = SOURCE.with(|s| {
        s.borrow()
            .as_ref()
            .filter(|(n, _)| n == name)
            .map(|(_, j)| j.clone().into_bytes())
    });
    let bytes = match injected {
        Some(b) => b,
        None => std::fs::read(dir().join(name)).expect("read vector file"),
    };
    let v: serde_json::Value = serde_json::from_slice(&bytes).expect("parse vector file");
    v["vectors"].as_array().expect("vectors array").clone()
}

fn hex(s: &str) -> Vec<u8> {
    assert!(s.len().is_multiple_of(2), "odd hex");
    (0..s.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&s[i..i + 2], 16).expect("hex digit"))
        .collect()
}

fn expect_err(debug: String, want: &str, name: &str) {
    assert!(
        debug.starts_with(want),
        "{name}: want error {want}, got {debug}"
    );
}

fn header_vectors_run() {
    for v in load("header.json") {
        let name = v["name"].as_str().unwrap();
        let bytes = hex(v["bytes_hex"].as_str().unwrap());
        match &v["expect"] {
            e if e.get("error").is_some() => {
                let err = header::decode(&bytes).unwrap_err();
                expect_err(format!("{err:?}"), e["error"].as_str().unwrap(), name);
            }
            e => {
                let (f, len) = header::decode(&bytes).unwrap();
                assert_eq!(len, bytes.len(), "{name}: trailing bytes");
                let kind = match e["kind"].as_str().unwrap() {
                    "hs" => header::Kind::Hs,
                    "data" => header::Kind::Data,
                    "close" => header::Kind::Close,
                    k => panic!("{name}: bad kind {k}"),
                };
                assert_eq!(f.kind, kind, "{name}");
                assert_eq!(f.step, e["step"].as_u64().unwrap() as u8, "{name}");
                assert_eq!(
                    f.purpose,
                    match e["purpose"].as_str() {
                        Some("companion") => Some(header::Purpose::Companion),
                        Some("pairing") => Some(header::Purpose::Pairing),
                        Some(_) | None => None,
                    },
                    "{name}"
                );
                let chan_hex = e["chan"].as_str().unwrap();
                assert_eq!(hex(chan_hex), f.chan.as_bytes(), "{name}");
                assert_eq!(
                    f.peer,
                    e["peer"].as_str().map(|s| Id::parse(s).unwrap()),
                    "{name}"
                );
                assert_eq!(f.ctr, e["ctr"].as_u64().unwrap(), "{name}");
                assert_eq!(f.body, hex(e["body_hex"].as_str().unwrap()).as_slice(), "{name}");
                // Byte-exact re-encode, and the relay's split-read path agrees.
                let head = header::Head {
                    kind: f.kind,
                    step: f.step,
                    purpose: f.purpose,
                    chan: f.chan,
                    peer: f.peer,
                    ctr: f.ctr,
                    body: f.body,
                };
                let mut enc = Vec::new();
                head.encode(&mut enc).unwrap();
                assert_eq!(enc, bytes, "{name}: re-encode");
                let split =
                    header::decode_header(&bytes[..header::HEADER_LEN], f.body.len()).unwrap();
                assert_eq!(
                    (split.kind, split.step, split.purpose, split.peer, split.ctr),
                    (f.kind, f.step, f.purpose, f.peer, f.ctr),
                    "{name}: split path"
                );
            }
        }
    }
}

fn record_vectors_run() {
    for v in load("record.json") {
        let name = v["name"].as_str().unwrap();
        let bytes = hex(v["bytes_hex"].as_str().unwrap());
        match &v["expect"] {
            e if e.get("error").is_some() => {
                let err = record::decode(&bytes).unwrap_err();
                expect_err(format!("{err:?}"), e["error"].as_str().unwrap(), name);
            }
            e => {
                let r = record::decode(&bytes).unwrap();
                assert_eq!(r.first, e["first"].as_bool().unwrap(), "{name}");
                assert_eq!(r.last, e["last"].as_bool().unwrap(), "{name}");
                assert_eq!(r.pad_only, e["pad_only"].as_bool().unwrap(), "{name}");
                assert_eq!(
                    r.mtype,
                    match e["mtype"].as_str() {
                        Some("json") => Some(record::MsgType::Json),
                        Some("term") => Some(record::MsgType::Term),
                        Some("ctrl") => Some(record::MsgType::Ctrl),
                        Some(_) | None => None,
                    },
                    "{name}"
                );
                assert_eq!(r.msg_id, e["msg_id"].as_u64().unwrap() as u32, "{name}");
                assert_eq!(r.total_len, e["total_len"].as_u64().unwrap() as u32, "{name}");
                assert_eq!(
                    r.content,
                    hex(e["content_hex"].as_str().unwrap()).as_slice(),
                    "{name}"
                );
                assert_eq!(r.len, bytes.len(), "{name}");
                // Byte-exact re-encode.
                let mut enc = Vec::new();
                record::encode(
                    &mut enc,
                    r.len,
                    r.first,
                    r.last,
                    r.pad_only,
                    r.mtype,
                    r.msg_id,
                    r.total_len,
                    r.content,
                )
                .unwrap();
                assert_eq!(enc, bytes, "{name}: re-encode");
            }
        }
    }
    // The fragmented TERM message reassembles across vectors.
    let frags = load("record.json");
    let mut re = record::Reassembler::new();
    let mut done = None;
    for want in ["term_frag_first", "term_frag_last"] {
        let v = frags.iter().find(|v| v["name"] == want).unwrap();
        let bytes = hex(v["bytes_hex"].as_str().unwrap());
        let r = record::decode(&bytes).unwrap();
        done = re.feed(&r).unwrap();
    }
    let done = done.unwrap();
    assert_eq!(done.mtype, record::MsgType::Term);
    assert_eq!(done.content.len(), 60);
}

fn term_vectors_run() {
    for v in load("term.json") {
        let name = v["name"].as_str().unwrap();
        let bytes = hex(v["bytes_hex"].as_str().unwrap());
        match &v["expect"] {
            e if e.get("error").is_some() => {
                let err = term::decode(&bytes).unwrap_err();
                expect_err(format!("{err:?}"), e["error"].as_str().unwrap(), name);
            }
            e => {
                let t = term::decode(&bytes).unwrap();
                assert_eq!(t.handle, e["handle"].as_u64().unwrap() as u32, "{name}");
                assert_eq!(t.seq, e["seq"].as_u64().unwrap(), "{name}");
                assert_eq!(t.base, e["base"].as_u64().unwrap(), "{name}");
                assert_eq!(t.total, e["total"].as_u64().unwrap(), "{name}");
                assert_eq!(t.alive, e["alive"].as_bool().unwrap(), "{name}");
                assert_eq!(t.reset, e["reset"].as_bool().unwrap(), "{name}");
                assert_eq!(
                    t.exit_code,
                    e["exit_code"].as_i64().map(|c| c as i32),
                    "{name}"
                );
                assert_eq!(
                    t.size,
                    e["size"].as_array().map(|s| (
                        s[0].as_u64().unwrap() as u16,
                        s[1].as_u64().unwrap() as u16
                    )),
                    "{name}"
                );
                assert_eq!(t.data, hex(e["data_hex"].as_str().unwrap()).as_slice(), "{name}");
                let head = term::TermHead {
                    handle: t.handle,
                    seq: t.seq,
                    base: t.base,
                    total: t.total,
                    alive: t.alive,
                    reset: t.reset,
                    exit_code: t.exit_code,
                    size: t.size,
                    data: t.data,
                };
                let mut enc = Vec::new();
                head.encode(&mut enc).unwrap();
                assert_eq!(enc, bytes, "{name}: re-encode");
            }
        }
    }
}

fn part_vectors_run() {
    let vecs = load("part.json");
    let by_name = |n: &str| vecs.iter().find(|v| v["name"] == n).unwrap();
    // Begin / chunks / end round-trip.
    let begin_bytes = by_name("begin_seed")["content_utf8"].as_str().unwrap().as_bytes();
    let begin = part::decode_begin(begin_bytes).unwrap();
    let e = &by_name("begin_seed")["expect"];
    assert_eq!(begin.part_id, e["part_id"].as_str().unwrap());
    assert_eq!(
        begin.purpose,
        match e["purpose"].as_str().unwrap() {
            "seed" => part::Purpose::Seed,
            "screen" => part::Purpose::Screen,
            "reply" => part::Purpose::Reply,
            p => panic!("bad purpose {p}"),
        }
    );
    assert_eq!(begin.request_id, None);
    assert_eq!(begin.stream_handle, Some(e["stream_handle"].as_u64().unwrap() as u32));
    assert_eq!(begin.total_bytes, e["total_bytes"].as_u64().unwrap());
    assert_eq!(begin.part_count, e["part_count"].as_u64().unwrap() as u32);
    assert_eq!(hex(e["sha256_hex"].as_str().unwrap()), begin.sha256);
    assert_eq!(part::encode_begin(&begin).unwrap(), begin_bytes);
    // The full session from vectors: atomic apply at part-end.
    let mut session = part::PartSession::open(begin);
    for n in ["chunk_0", "chunk_1"] {
        let c = by_name(n);
        let chunk = part::decode_chunk(c["json_utf8"].as_str().unwrap().as_bytes()).unwrap();
        let ce = &c["expect"];
        assert_eq!(chunk.part_id, ce["part_id"].as_str().unwrap());
        assert_eq!(chunk.index, ce["index"].as_u64().unwrap() as u32);
        assert_eq!(chunk.bytes, hex(ce["bytes_hex"].as_str().unwrap()));
        assert_eq!(
            part::decode_chunk(
                &part::encode_chunk(&chunk.part_id, chunk.index, &chunk.bytes).unwrap()
            )
            .unwrap(),
            chunk
        );
        session.feed(chunk).unwrap();
    }
    let payload = session
        .end(&part::decode_end(by_name("end")["content_utf8"].as_str().unwrap().as_bytes()).unwrap())
        .unwrap();
    assert_eq!(payload, vec![9u8; 100]);
    // Error vectors.
    for v in &vecs {
        if let Some(want) = v.get("expect_error").and_then(|e| e.as_str()) {
            let content = v["content_utf8"].as_str().unwrap().as_bytes();
            // `part-begin` contents decode as begins; anything else must fail
            // as a begin too (wrong command word).
            let err = part::decode_begin(content).unwrap_err();
            let debug = format!("{err:?}");
            assert!(
                debug.starts_with(want) || (want.contains("or") && debug.starts_with("WrongCommand")),
                "{}: want {want}, got {debug}",
                v["name"].as_str().unwrap()
            );
        }
    }
}

fn catalog_blob_vectors_run() {
    for v in load("catalog_blob.json") {
        let name = v["name"].as_str().unwrap();
        let bytes = hex(v["bytes_hex"].as_str().unwrap());
        if let Some(want) = v.get("expect_error").and_then(|e| e.as_str()) {
            let err = catalog_blob::decode(&bytes).unwrap_err();
            expect_err(format!("{err:?}"), want, name);
            continue;
        }
        let e = &v["expect"];
        let blob = catalog_blob::decode(&bytes).unwrap();
        assert_eq!(blob.desktop, Id::parse(e["desktop"].as_str().unwrap()).unwrap(), "{name}");
        assert_eq!(blob.version, e["version"].as_u64().unwrap(), "{name}");
        assert_eq!(blob.recipients.len(), e["recipients"].as_array().unwrap().len(), "{name}");
        for (r, re) in blob.recipients.iter().zip(e["recipients"].as_array().unwrap()) {
            assert_eq!(r.phone, Id::parse(re["phone"].as_str().unwrap()).unwrap(), "{name}");
            assert_eq!(r.wrap, hex(re["wrap_hex"].as_str().unwrap()), "{name}");
        }
        assert_eq!(blob.nonce, hex(e["nonce_hex"].as_str().unwrap()).as_slice(), "{name}");
        assert_eq!(blob.body, hex(e["body_hex"].as_str().unwrap()), "{name}");
        assert_eq!(bytes.len() % catalog_blob::PAD_BUCKET, 0, "{name}");
        assert_eq!(blob.encode().unwrap(), bytes, "{name}: re-encode");
    }
}

fn push_vectors_run() {
    for v in load("push.json") {
        let name = v["name"].as_str().unwrap();
        let bytes = hex(v["bytes_hex"].as_str().unwrap());
        if let Some(want) = v.get("expect_error").and_then(|e| e.as_str()) {
            let err = push_plain::decode(&bytes).unwrap_err();
            expect_err(format!("{err:?}"), want, name);
            continue;
        }
        let e = &v["expect"];
        let p = push_plain::decode(&bytes).unwrap();
        assert_eq!(bytes.len(), push_plain::PLAINTEXT_LEN, "{name}");
        assert_eq!(p.desktop_id, Id::parse(e["desktop_id"].as_str().unwrap()).unwrap(), "{name}");
        assert_eq!(p.id, hex(e["id_hex"].as_str().unwrap()).as_slice(), "{name}");
        assert_eq!(p.issued_at_ms, e["issued_at_ms"].as_u64().unwrap(), "{name}");
        assert_eq!(p.kind, e["kind"].as_u64().unwrap() as u8, "{name}");
        assert_eq!(p.dismiss, e["dismiss"].as_bool().unwrap(), "{name}");
        assert_eq!(p.title, e["title"].as_str().unwrap(), "{name}");
        assert_eq!(p.body, e["body"].as_str().unwrap(), "{name}");
        assert_eq!(p.workspace_id, Id::parse(e["workspace_id"].as_str().unwrap()).unwrap(), "{name}");
        assert_eq!(p.tab_id, Id::parse(e["tab_id"].as_str().unwrap()).unwrap(), "{name}");
        let want_ids: Vec<Vec<u8>> = e["dismiss_ids"]
            .as_array()
            .unwrap()
            .iter()
            .map(|s| hex(s.as_str().unwrap()))
            .collect();
        assert_eq!(p.dismiss_ids.len(), want_ids.len(), "{name}");
        for (got, want) in p.dismiss_ids.iter().zip(&want_ids) {
            assert_eq!(got, want.as_slice(), "{name}");
        }
        assert_eq!(p.encode().unwrap().as_slice(), bytes.as_slice(), "{name}: re-encode");
    }
    // The maxima the size proof relies on (§8): 919 and 1,007 bytes.
    assert_eq!(push_plain::FIXED_LEN + 240 + 600, 919);
    assert_eq!(push_plain::FIXED_LEN + 58 * 16, 1007);
}

fn hs_vectors_run() {
    for v in load("hs.json") {
        let name = v["name"].as_str().unwrap();
        if let Some(want) = v.get("expect_error").and_then(|e| e.as_str()) {
            let json = v["json_utf8"].as_str().unwrap().as_bytes();
            let err = match v["kind"].as_str() {
                Some("pairing") => format!("{:?}", hs::decode_pairing(json).unwrap_err()),
                _ => format!("{:?}", hs::decode_hello(json).unwrap_err()),
            };
            expect_err(err, want, name);
            continue;
        }
        let json = v["json_utf8"].as_str().unwrap();
        let e = &v["expect"];
        if name == "kk_hello" {
            let h = hs::decode_hello(json.as_bytes()).unwrap();
            let caps: Vec<String> = e["caps"]
                .as_array()
                .unwrap()
                .iter()
                .map(|c| c.as_str().unwrap().to_string())
                .collect();
            assert_eq!(h.caps, caps);
            assert_eq!(hs::encode_hello(&h).unwrap(), json.as_bytes());
        } else {
            let p = hs::decode_pairing(json.as_bytes()).unwrap();
            assert_eq!(p.device_name, e["device_name"].as_str().unwrap());
            assert_eq!(
                p.platform,
                match e["platform"].as_str().unwrap() {
                    "ios" => hs::Platform::Ios,
                    "android" => hs::Platform::Android,
                    x => panic!("bad platform {x}"),
                }
            );
            assert_eq!(p.push_pub, hex(e["push_pub_hex"].as_str().unwrap()).as_slice());
            assert_eq!(hs::encode_pairing(&p).unwrap(), json.as_bytes());
        }
    }
}

#[test]
fn b64url_sealed_push_size_holds() {
    // §8: 1,120 sealed bytes are 1,494 base64url characters (no padding).
    assert_eq!(crate::codec::b64::encode(&vec![0u8; 1120]).len(), 1494);
}

