/// Run one `vectors/codec/<name>` file given as JSON text (the `vectors`
/// feature: the phone module runs these on the simulators, §12.1). Panics on
/// the first mismatch, like the tests; returns how many vectors the file has.
pub fn run_json(name: &str, json: &str) -> usize {
    let run: fn() = match name {
        "header.json" => header_vectors_run,
        "record.json" => record_vectors_run,
        "term.json" => term_vectors_run,
        "part.json" => part_vectors_run,
        "catalog_blob.json" => catalog_blob_vectors_run,
        "push.json" => push_vectors_run,
        "hs.json" => hs_vectors_run,
        other => panic!("unknown codec vector file {other}"),
    };
    SOURCE.with(|s| *s.borrow_mut() = Some((name.to_string(), json.to_string())));
    struct Clear;
    impl Drop for Clear {
        fn drop(&mut self) {
            SOURCE.with(|s| *s.borrow_mut() = None);
        }
    }
    let _clear = Clear;
    run();
    load(name).len()
}
